import re
import json
from datetime import datetime, timezone, timedelta
from collections import defaultdict

SYSLOG_RE = re.compile(
    r"<\d+>(?P<ts>\w{3}\s+\d{1,2}\s\d{2}:\d{2}:\d{2})\s\S+\ssshd\[\d+\]:\s"
    r"Failed password for (?P<user>\S+) from (?P<ip>\d+\.\d+\.\d+\.\d+)"
)

def parse_syslog(path, local_tz_offset_hours, year):
    events = []
    with open(path) as f:
        for line in f:
            m = SYSLOG_RE.search(line)
            if not m:
                continue
            local_dt = datetime.strptime(f"{year} {m['ts']}", "%Y %b %d %H:%M:%S")
            utc_dt = local_dt.replace(tzinfo=timezone(timedelta(hours=local_tz_offset_hours))).astimezone(timezone.utc)
            events.append({"timestamp": utc_dt, "source_ip": m["ip"], "username": m["user"], "source": "syslog"})
    return events

def parse_idp_json(path):
    events = []
    with open(path) as f:
        for line in f:
            rec = json.loads(line)
            if rec.get("status", {}).get("errorCode", 0) == 0:
                continue  # successful sign-in, not a failure
            ts = datetime.fromisoformat(rec["createdDateTime"].replace("Z", "+00:00"))
            events.append({
                "timestamp": ts, "source_ip": rec["ipAddress"],
                "username": rec["userPrincipalName"], "source": "idp",
            })
    return events

def detect_password_spray(events, window_minutes=10, user_threshold=5):
    by_ip = defaultdict(list)
    for e in events:
        by_ip[e["source_ip"]].append(e)

    findings = []
    window = timedelta(minutes=window_minutes)
    for ip, ip_events in by_ip.items():
        ip_events.sort(key=lambda e: e["timestamp"])
        left = 0
        for right in range(len(ip_events)):
            while ip_events[right]["timestamp"] - ip_events[left]["timestamp"] > window:
                left += 1
            users_in_window = {e["username"] for e in ip_events[left:right + 1]}
            if len(users_in_window) >= user_threshold:
                findings.append({
                    "source_ip": ip,
                    "window_start": ip_events[left]["timestamp"],
                    "window_end": ip_events[right]["timestamp"],
                    "usernames": sorted(users_in_window),
                })
    return findings

if __name__ == "__main__":
    all_events = (
        parse_syslog("edge_fw.log", local_tz_offset_hours=-4, year=2026)
        + parse_idp_json("idp_signins.jsonl")
    )
    for finding in detect_password_spray(all_events):
        print(finding)

import requests

def isolate_device(device_id: str, token: str, comment: str, isolation_type: str = "Selective") -> int:
    resp = requests.post(
        f"https://api.securitycenter.microsoft.com/api/machines/{device_id}/isolate",
        headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
        json={"Comment": comment, "IsolationType": isolation_type},
        timeout=10,
    )
    return resp.status_code  # 201 Accepted on success

