import requests
import time
import random
import uuid

def is_retryable(exc: Exception) -> bool:
    if isinstance(exc, requests.Timeout):
        return True
    if isinstance(exc, requests.HTTPError):
        return exc.response.status_code in (429, 500, 502, 503, 504)
    return False

def block_ip(ip_address: str) -> dict:
    key = str(uuid.uuid4())
    resp = requests.post(
        "https://firewall.internal.example.com/api/blocks",
        json={"ip": ip_address},
        headers={"Idempotency-Key": key, "Authorization": f"Bearer {API_TOKEN}"},
        timeout=5,
    )
    resp.raise_for_status()
    return resp.json()

def call_with_backoff(func, *args, max_attempts=5, **kwargs):
    for attempt in range(1, max_attempts + 1):
        try:
            return func(*args, **kwargs)
        except Exception as exc:
            if not is_retryable(exc) or attempt == max_attempts:
                raise
            delay = min(2 ** attempt, 30) + random.uniform(0, 1)
            time.sleep(delay)

# called from the playbook:
result = call_with_backoff(block_ip, "203.0.113.44")
